 useEffect(()=>{let active=true;(async()=>{try{const saved=await AsyncStorage.getItem(AUTH_TOKEN_KEY);if(active&&saved)setToken(saved)}catch(e){console.warn('Could not restore saved login',e)}finally{if(active)setSessionReady(true)}})();return()=>{active=false}},[]);
