 const scheduleMatchReminder=async match=>{try{if(Platform.OS==='android')await Notifications.setNotificationChannelAsync('match-reminders',{name:'Match reminders',importance:Notifications.AndroidImportance.HIGH,sound:'default'});const permission=await Notifications.getPermissionsAsync();let granted=permission.granted;if(!granted){const asked=await Notifications.requestPermissionsAsync();granted=asked.granted;}if(!granted)return;const fireAt=new Date(new Date(match.starts_at).getTime()-5*60*1000);if(fireAt.getTime()<=Date.now())return;await Notifications.scheduleNotificationAsync({content:{title:'ZYROX ARENA · Match Reminder',body:`${match.title||'Your match'} starts in 5 minutes. Get ready!`,sound:'default',data:{matchId:match.id}},trigger:{type:Notifications.SchedulableTriggerInputTypes.DATE,date:fireAt,channelId:'match-reminders'}});}catch(e){console.warn('Could not schedule local match reminder',e)}};
 useEffect(()=>{if(token&&tab==='referral')run(async()=>{const [d,b]=await Promise.all([api('/referrals/me'),api('/referrals/leaderboard?period=monthly')]);setReferralData(d);setReferralBoard(b)})},[token,tab]);
 useEffect(()=>{const applyReferralUrl=url=>{if(!url)return;const m=String(url).match(/[?&]ref=([^&]+)/i);if(m){let code=m[1];try{code=decodeURIComponent(code)}catch{}setAuth(p=>({...p,referral_code:code.toUpperCase()}));setAuthMode('register');setTab('home')}};Linking.getInitialURL().then(applyReferralUrl).catch(()=>{});const sub=Linking.addEventListener('url',e=>applyReferralUrl(e.url));return()=>sub?.remove?.()},[]);
 const login=()=>run(async()=>{const d=authMode==='register'?await api('/auth/register','POST',{name:auth.name,email:auth.email||undefined,phone:auth.phone||undefined,password:auth.password,referral_code:auth.referral_code||undefined}):await api('/auth/login','POST',{identifier:auth.identifier,password:auth.password});if(!d?.token)throw Error('Server did not return an authentication token');await AsyncStorage.setItem(AUTH_TOKEN_KEY,d.token);setToken(d.token)});
