 const field=(key,label,placeholder='',keyboardType='default',secure=false)=> <View style={S.field} key={key}><Text style={S.label}>{label}</Text><TextInput value={String(form[key]??'')} onChangeText={v=>setForm(p=>({...p,[key]:v}))} placeholder={placeholder||label} placeholderTextColor={C.muted} keyboardType={keyboardType} secureTextEntry={secure} style={S.input}/></View>;
