class AppErrorBoundary extends React.Component {
 constructor(props){super(props);this.state={hasError:false}}
 static getDerivedStateFromError(){return {hasError:true}}
 componentDidCatch(error,info){console.error('ZYROX ARENA render error:',error,info?.componentStack)}
 render(){if(this.state.hasError)return <SafeAreaView style={{flex:1,backgroundColor:'#07111f',justifyContent:'center',alignItems:'center',padding:24}}><Text style={{color:'#f4f8ff',fontSize:20,fontWeight:'900',marginBottom:10}}>ZYROX ARENA</Text><Text style={{color:'#91a5bb',fontSize:13,textAlign:'center',marginBottom:16}}>A screen could not be displayed. Please restart the app. Your saved login will remain available.</Text><TouchableOpacity onPress={()=>this.setState({hasError:false})} style={{backgroundColor:'#00d5e9',paddingHorizontal:24,paddingVertical:12,borderRadius:10,alignSelf:'center',minWidth:130}}><Text style={{color:'#07111f',fontWeight:'900'}}>TRY AGAIN</Text></TouchableOpacity></SafeAreaView>;return this.props.children}
}

export default function App(){return <SafeAreaProvider><AppErrorBoundary><AppContent/></AppErrorBoundary></SafeAreaProvider>}
